class TaskBinding{static Object value(long m,long n){return new alternate.Fraction(m,n);}static long[]parts(Object f){return new long[]{((alternate.Fraction)f).numerator(),((alternate.Fraction)f).denominator()};}static Object operation(Object a,Object b,int op){alternate.Fraction x=(alternate.Fraction)a,y=(alternate.Fraction)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static String text(Object f){return f.toString();}}
